/* ============ SHEETS API ============ */
async function fetchRange(tab, range){
  const full = `'${tab}'!${range}`;
  const url = `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/${encodeURIComponent(full)}?key=${API_KEY}&valueRenderOption=FORMATTED_VALUE`;
  const res = await fetch(url);
  if(!res.ok){
    let msg = `Lá»—i táº£i dá»¯ liá»‡u (mÃ£ ${res.status})`;
    try{ const j = await res.json(); if(j?.error?.message) msg += ': ' + j.error.message; }catch(e){}
    if(res.status===403 || res.status===400) msg += '. Kiá»ƒm tra láº¡i: Sheet Ä‘Ã£ báº­t "Anyone with the link - Viewer" chÆ°a? API key Ä‘Ã£ báº­t Ä‘Ãºng Google Sheets API chÆ°a?';
    throw new Error(msg);
  }
  const data = await res.json();
  return data.values || [];
}

function forwardFill(row){
  let last=''; return (row||[]).map(c=>{ const v=(c||'').trim(); if(v) last=v; return last; });
}
function parseMoney(v){
  if(!v) return 0;
  const cleaned = String(v).replace(/[^\d-]/g,'');
  return cleaned ? parseInt(cleaned,10) : 0;
}
function formatMoney(n){
  return (n||0).toLocaleString('vi-VN') + ' Ä‘';
}
function parseVNDate(s){
  const m = /(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(s||'');
  if(!m) return 0;
  return new Date(+m[3], +m[2]-1, +m[1]).getTime();
}
async function sha256Hex(str){
  const enc = new TextEncoder().encode(str);
  const buf = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
}

/*
  Danh sÃ¡ch ngÆ°á»i dÃ¹ng + mÃ£ PIN (Ä‘Ã£ bÄƒm SHA-256) Ä‘Æ°á»£c Ä‘á»c tá»« tab "PIN" trong
  Google Sheet, thay vÃ¬ Ä‘á»ƒ cá»©ng trong code nhÆ° trÆ°á»›c â€” Ä‘á»ƒ khi Ä‘Æ°a code lÃªn
  GitHub thÃ¬ khÃ´ng lá»™ mÃ£ PIN tháº­t cá»§a ai, vÃ  quáº£n lÃ½ cÃ³ thá»ƒ tá»± thÃªm/sá»­a ngÆ°á»i
  dÃ¹ng ngay trong Sheet mÃ  khÃ´ng cáº§n sá»­a code.
  Cáº¥u trÃºc tab "PIN" cáº§n cÃ³: cá»™t "Há» vÃ  tÃªn", "Vai trÃ²" (driver/manager), "PIN Hash".
*/
async function parseUsers(){
  const rows = await fetchRange(TAB_PIN, 'A1:C50');
  const headerIdx = rows.findIndex(r=>r.some(c=>(c||'').trim()==='Há» vÃ  tÃªn'));
  if(headerIdx===-1) throw new Error(`KhÃ´ng tÃ¬m tháº¥y cá»™t "Há» vÃ  tÃªn" trong tab "${TAB_PIN}". Xem hÆ°á»›ng dáº«n táº¡o tab PIN trong APPS_SCRIPT_SETUP.md.`);
  const headers = rows[headerIdx].map(h=>(h||'').trim());
  const nameCol = headers.indexOf('Há» vÃ  tÃªn');
  const roleCol = headers.indexOf('Vai trÃ²');
  const pinCol = headers.indexOf('PIN Hash');
  if(pinCol===-1) throw new Error(`KhÃ´ng tÃ¬m tháº¥y cá»™t "PIN Hash" trong tab "${TAB_PIN}".`);
  const users = [];
  for(let i=headerIdx+1;i<rows.length;i++){
    const r = rows[i];
    if(!r || !r[nameCol] || !r[nameCol].trim()) continue;
    users.push({
      name: r[nameCol].trim(),
      role: (r[roleCol]||'').trim().toLowerCase()==='manager' ? 'manager' : 'driver',
      pinHash: (r[pinCol]||'').trim().toLowerCase(),
    });
  }
  return users;
}
async function loadUsers(){
  if(state.users) return state.users;
  state.usersLoading = true; state.usersError = null; render();
  try{
    const users = await parseUsers();
    state.users = users;
    return users;
  }catch(e){
    state.usersError = e.message || String(e);
    throw e;
  }finally{
    state.usersLoading = false; render();
  }
}
async function retryLoadUsers(){
  try{ await loadUsers(); }catch(e){}
}

async function parseTrips(){
  const rows = await fetchRange(TAB_TRIPS, 'A9:BZ3000');
  if(rows.length<3) throw new Error(`KhÃ´ng Ä‘á»c Ä‘Æ°á»£c dá»¯ liá»‡u tá»« tab "${TAB_TRIPS}".`);
  const mainFilled = forwardFill(rows[0]);
  const sub = (rows[1]||[]).map(c=>(c||'').trim());
  const colDriver = mainFilled.findIndex(h=>h.includes('TÃªn lÃ¡i xe'));
  const colDate = sub.findIndex(h=>h.toUpperCase()==='DATE');
  const colWage = mainFilled.findIndex(h=>h.includes('LÆ°Æ¡ng lÃ¡i xe theo chuyáº¿n'));
  const bonusCols = mainFilled.map((h,i)=>h.includes('PhÃ­ tráº£ lÃ¡i xe')?i:-1).filter(i=>i!==-1);
  const colRoute = mainFilled.findIndex(h=>h.includes('Tuyáº¿n váº­n chuyá»ƒn'));
  const colNote = mainFilled.findIndex(h=>h.toUpperCase().includes('GHI CHÃš'));
  if(colDriver===-1 || colDate===-1 || colWage===-1){
    throw new Error(`KhÃ´ng tÃ¬m tháº¥y Ä‘á»§ cá»™t cáº§n thiáº¿t trong tab "${TAB_TRIPS}" (TÃªn lÃ¡i xe / DATE / LÆ°Æ¡ng lÃ¡i xe theo chuyáº¿n). Cáº¥u trÃºc báº£ng cÃ³ thá»ƒ Ä‘Ã£ thay Ä‘á»•i so vá»›i ban Ä‘áº§u.`);
  }
  const records = [];
  for(let i=2;i<rows.length;i++){
    const r = rows[i];
    if(!r || !r[colDriver] || !r[colDriver].trim()) continue;
    const wage = parseMoney(r[colWage]);
    const bonus = bonusCols.reduce((s,ci)=>s+parseMoney(r[ci]),0);
    records.push({
      driver: r[colDriver].trim(),
      date: (r[colDate]||'').trim(),
      route: colRoute!==-1 ? (r[colRoute]||'').trim() : '',
      note: colNote!==-1 ? (r[colNote]||'').trim() : '',
      wage, bonus, total: wage+bonus,
    });
  }
  return records;
}

async function parseSalary(){
  const rows = await fetchRange(TAB_SALARY, 'A1:AZ200');
  const headerIdx = rows.findIndex(r=>r.some(c=>(c||'').trim()==='Há» vÃ  tÃªn'));
  if(headerIdx===-1) throw new Error(`KhÃ´ng tÃ¬m tháº¥y cá»™t "Há» vÃ  tÃªn" trong tab "${TAB_SALARY}".`);
  const headers = rows[headerIdx].map(h=>(h||'').trim());
  const nameCol = headers.findIndex(h=>h==='Há» vÃ  tÃªn');
  const records = [];
  for(let i=headerIdx+1;i<rows.length;i++){
    const r = rows[i];
    if(!r || !r[nameCol] || !r[nameCol].trim()) continue;
    const obj = {};
    headers.forEach((h,idx)=>{ if(h) obj[h] = r[idx]!==undefined ? r[idx] : ''; });
    records.push(obj);
  }
  return { headers, records, nameCol };
}

/*
  Nháº­n diá»‡n ná»™i dung 1 Ã´ cháº¥m cÃ´ng. TrÆ°á»›c Ä‘Ã¢y code chá»‰ coi lÃ  "cÃ³ cÃ´ng" khi Ã´
  Ä‘Ãºng báº±ng "X" â€” má»i kÃ½ hiá»‡u khÃ¡c (vÃ­ dá»¥ ná»­a cÃ´ng: "1/2", "X/2", "0.5", "Ná»­a")
  bá»‹ coi nhÆ° Ã´ trá»‘ng, khiáº¿n ngÃ y Ä‘Ã³ biáº¿n máº¥t khá»i thá»‘ng kÃª. Giá»:
    - "X"                              -> cÃ´ng Ä‘áº§y Ä‘á»§ (full, 1 cÃ´ng)
    - "1/2", "X/2", "0.5", "ná»­a", ...  -> ná»­a cÃ´ng (half, 0.5 cÃ´ng)
    - "-", "nghá»‰", "off", Ã´ trá»‘ng      -> nghá»‰ (off, 0 cÃ´ng)
    - báº¥t ká»³ ná»™i dung khÃ¡c khÃ´ng rá»—ng  -> váº«n giá»¯ láº¡i & hiá»ƒn thá»‹ (other),
      tÃ­nh lÃ  1 cÃ´ng, Ä‘á»ƒ khÃ´ng bao giá» máº¥t dá»¯ liá»‡u dÃ¹ kÃ½ hiá»‡u trong Sheet lÃ  gÃ¬.
*/
function parseMark(v){
  const raw = (v||'').trim();
  if(!raw) return { status:'off', value:0, label:'' };
  const up = raw.toUpperCase().replace(/\s+/g,'');
  if(up==='X') return { status:'full', value:1, label:'X' };
  if(up==='1/2' || up==='X/2' || up==='0.5' || up==='0,5' || up.includes('Ná»¬A') || up.includes('HALF')){
    return { status:'half', value:0.5, label:'Â½' };
  }
  if(up==='-' || up==='NGHá»ˆ' || up==='OFF' || up==='O'){
    return { status:'off', value:0, label:'' };
  }
  return { status:'other', value:1, label:raw };
}

async function parseAttendance(){
  const rows = await fetchRange(TAB_ATTEND, 'A1:BZ60');
  const nameRowIdx = rows.findIndex(r=>r.some(c=>(c||'').trim()==='Há» vÃ  tÃªn'));
  if(nameRowIdx===-1) throw new Error(`KhÃ´ng tÃ¬m tháº¥y cá»™t "Há» vÃ  tÃªn" trong tab "${TAB_ATTEND}".`);
  const weekdayRow = rows[nameRowIdx];
  const dateRow = rows[nameRowIdx+1] || [];
  const nameCol = weekdayRow.findIndex(c=>(c||'').trim()==='Há» vÃ  tÃªn');
  const dateCols = [];
  const maxLen = Math.max(weekdayRow.length, dateRow.length);
  for(let j=nameCol+1;j<maxLen;j++){
    const dv = (dateRow[j]||'').trim();
    if(dv) dateCols.push({ idx:j, date:dv, weekday:(weekdayRow[j]||'').trim() });
  }
  const records = [];
  for(let i=nameRowIdx+2;i<rows.length;i++){
    const r = rows[i];
    if(!r || !r[nameCol] || !r[nameCol].trim()) continue;
    const marks = dateCols.map(dc=>{
      const m = parseMark(r[dc.idx]);
      return { ...dc, ...m, present: m.status!=='off' };
    });
    const total = marks.reduce((s,m)=>s+m.value,0);
    records.push({ name:r[nameCol].trim(), marks, total });
  }
  return records;
}

async function loadData(key, loader){
  if(state.cache[key]) return state.cache[key];
  state.loading[key]=true; state.errors[key]=null; render();
  try{
    const data = await loader();
    state.cache[key] = data;
    return data;
  }catch(e){
    state.errors[key] = e.message || String(e);
    throw e;
  }finally{
    state.loading[key]=false; render();
  }
}
function invalidate(key){ delete state.cache[key]; }

