function setLoginRole(role){ state.loginRole = role; render(); }
async function doLogin(){
  const pin = document.getElementById('pinInput').value.trim();
  const errEl = document.getElementById('loginError');
  errEl.textContent = '';
  if(!pin){ errEl.textContent = 'Vui lÃ²ng nháº­p mÃ£ PIN.'; return; }
  const candidates = (state.users||[]).filter(u=>{
    if(u.role!==state.loginRole) return false;
    if(state.loginRole==='driver'){
      const name = document.getElementById('driverSelect').value;
      return u.name===name;
    }
    return true;
  });
  if(candidates.length===0){ errEl.textContent = 'KhÃ´ng tÃ¬m tháº¥y ngÆ°á»i dÃ¹ng phÃ¹ há»£p.'; return; }
  const hash = await sha256Hex(pin);
  const matched = candidates.find(u=>u.pinHash===hash);
  if(!matched){ errEl.textContent = 'MÃ£ PIN khÃ´ng Ä‘Ãºng. Vui lÃ²ng thá»­ láº¡i.'; return; }
  state.user = matched;
  state.cache = {}; state.errors = {};
  render();
}
