async function submitChangePin(){
  const oldPin = document.getElementById('oldPin').value.trim();
  const newPin = document.getElementById('newPin').value.trim();
  const newPin2 = document.getElementById('newPin2').value.trim();
  const msgEl = document.getElementById('pinModalMsg');
  const btn = document.getElementById('pinSubmitBtn');
  msgEl.style.color = 'var(--red)';
  msgEl.textContent = '';
  if(!oldPin || !newPin || !newPin2){ msgEl.textContent = 'Vui lÃ²ng nháº­p Ä‘áº§y Ä‘á»§ cÃ¡c Ã´.'; return; }
  if(newPin.length < 4){ msgEl.textContent = 'MÃ£ PIN má»›i cáº§n tá»‘i thiá»ƒu 4 sá»‘.'; return; }
  if(newPin === oldPin){ msgEl.textContent = 'MÃ£ PIN má»›i cáº§n khÃ¡c mÃ£ PIN hiá»‡n táº¡i.'; return; }
  if(newPin !== newPin2){ msgEl.textContent = 'MÃ£ PIN má»›i nháº­p láº¡i khÃ´ng khá»›p.'; return; }
  if(!APPS_SCRIPT_URL || APPS_SCRIPT_URL.includes('DÃN_URL')){
    msgEl.textContent = 'ChÆ°a cáº¥u hÃ¬nh APPS_SCRIPT_URL trong code â€” xem hÆ°á»›ng dáº«n trong APPS_SCRIPT_SETUP.md.';
    return;
  }
  btn.disabled = true; btn.textContent = 'Äang lÆ°uâ€¦';
  try{
    const oldHash = await sha256Hex(oldPin);
    const newHash = await sha256Hex(newPin);
    let res;
    try{
      res = await fetch(APPS_SCRIPT_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action:'changePin', name: state.user.name, role: state.user.role, oldHash, newHash }),
      });
    }catch(networkErr){
      // ThÆ°á»ng do URL Apps Script sai/Ä‘Ã£ xoÃ¡, hoáº·c cháº·n máº¡ng (CORS/adblock/offline)
      throw new Error('KhÃ´ng káº¿t ná»‘i Ä‘Æ°á»£c tá»›i mÃ¡y chá»§ (Apps Script). Kiá»ƒm tra máº¡ng, hoáº·c URL APPS_SCRIPT_URL cÃ³ cÃ²n Ä‘Ãºng khÃ´ng.');
    }
    const raw = await res.text();
    let data;
    try{
      data = JSON.parse(raw);
    }catch(parseErr){
      // Apps Script khÃ´ng tráº£ JSON nhÆ° mong Ä‘á»£i -> thÆ°á»ng lÃ  do deploy sai
      // (chÆ°a "New deployment" sau khi sá»­a Code.gs, hoáº·c "Ai cÃ³ quyá»n truy cáº­p"
      // khÃ´ng pháº£i "Anyone" nÃªn bá»‹ chuyá»ƒn hÆ°á»›ng sang trang Ä‘Äƒng nháº­p Google).
      console.error('Pháº£n há»“i thÃ´ tá»« Apps Script (khÃ´ng pháº£i JSON):', raw);
      throw new Error('MÃ¡y chá»§ tráº£ vá» dá»¯ liá»‡u khÃ´ng há»£p lá»‡ (cÃ³ thá»ƒ do chÆ°a deploy Ä‘Ãºng Apps Script â€” xem console Ä‘á»ƒ biáº¿t chi tiáº¿t, hoáº·c má»Ÿ URL Apps Script trá»±c tiáº¿p báº±ng trÃ¬nh duyá»‡t Ä‘á»ƒ kiá»ƒm tra).');
    }
    if(!data.ok) throw new Error(data.error || 'KhÃ´ng thá»ƒ Ä‘á»•i mÃ£ PIN.');
    state.user.pinHash = newHash;
    if(state.users){
      const u = state.users.find(u=>u.name===state.user.name && u.role===state.user.role);
      if(u) u.pinHash = newHash;
    }
    msgEl.style.color = 'var(--teal)';
    msgEl.textContent = 'Äá»•i mÃ£ PIN thÃ nh cÃ´ng!';
    setTimeout(()=>{ state.showPinModal = false; render(); }, 900);
  }catch(e){
    msgEl.style.color = 'var(--red)';
    msgEl.textContent = e.message || 'CÃ³ lá»—i xáº£y ra, vui lÃ²ng thá»­ láº¡i.';
    btn.disabled = false; btn.textContent = 'LÆ°u mÃ£ PIN má»›i';
  }
}

