/* ============ DRIVER: DAILY EARNINGS ============ */
async function renderDailyTab(){
  const key='trips';
  if(state.loading[key]) return `<div class="loading">Äang táº£i dá»¯ liá»‡u chuyáº¿n Ä‘iâ€¦</div>`;
  if(state.errors[key]) return errorPanel(state.errors[key], key, ()=>{invalidate(key); loadThenRender();});
  let trips;
  try{ trips = await loadData(key, parseTrips); }catch(e){ return ''; }
  const mine = trips.filter(t=>t.driver===state.user.name);
  const map = new Map();
  mine.forEach(t=>{
    if(!map.has(t.date)) map.set(t.date,{date:t.date, trips:[], total:0});
    const g = map.get(t.date); g.trips.push(t); g.total += t.total;
  });
  const days = Array.from(map.values()).sort((a,b)=>parseVNDate(b.date)-parseVNDate(a.date));
  const cumTotal = mine.reduce((s,t)=>s+t.total,0);

  return `
    <div class="cum-banner">
      <div><div class="cum-label">Tá»•ng lÆ°Æ¡ng chuyáº¿n + phá»¥ cáº¥p (tá»« Ä‘áº§u thÃ¡ng Ä‘áº¿n nay)</div><div class="cum-value">${formatMoney(cumTotal)}</div></div>
      <div class="cum-label">${mine.length} chuyáº¿n</div>
    </div>
    <div class="panel">
      <div class="refresh-row">
        <div><div class="section-title">Thu nháº­p theo ngÃ y</div><div class="section-sub" style="margin:0;">LÆ°Æ¡ng chuyáº¿n + phá»¥ cáº¥p phÃ¡t sinh (vÃ© kho, bá»‘c xáº¿p, ghÃ©p hÃ ng, chá»§ nháº­t, chá» giá», Äƒn ca 2, tÄƒng ca). ChÆ°a gá»“m lÆ°Æ¡ng cÆ¡ báº£n & phá»¥ cáº¥p cá»‘ Ä‘á»‹nh â€” xem á»Ÿ tab "Báº£ng lÆ°Æ¡ng thÃ¡ng".</div></div>
        <button class="refresh-btn" onclick="invalidate('trips'); loadThenRender();">â†» LÃ m má»›i</button>
      </div>
      ${days.length===0 ? `<div class="empty">ChÆ°a cÃ³ dá»¯ liá»‡u chuyáº¿n nÃ o Ä‘Æ°á»£c ghi nháº­n cho báº¡n.</div>` : `
      <div class="route-line">
        ${days.map((d,i)=>`
          <div class="day-card ${state.openDay===d.date?'open':''}" onclick="toggleDay('${d.date}')">
            <div class="day-head">
              <div><div class="day-date">${d.date}</div><div class="day-count">${d.trips.length} chuyáº¿n</div></div>
              <div class="day-total mono">${formatMoney(d.total)}</div>
            </div>
            <div class="trip-list">
              ${d.trips.map(t=>`
                <div class="trip-row">
                  <div class="trip-route">${t.route || t.note || 'Chuyáº¿n hÃ ng'}</div>
                  <div class="trip-amt">${formatMoney(t.total)}</div>
                </div>`).join('')}
            </div>
          </div>`).join('')}
      </div>`}
    </div>`;
}
function toggleDay(date){ state.openDay = state.openDay===date ? null : date; render(); }

/* ============ DRIVER: MONTHLY SALARY ============ */
async function renderSalaryTab(){
  const key='salary';
  if(state.loading[key]) return `<div class="loading">Äang táº£i báº£ng lÆ°Æ¡ngâ€¦</div>`;
  if(state.errors[key]) return errorPanel(state.errors[key], key, ()=>{invalidate(key); loadThenRender();});
  let data;
  try{ data = await loadData(key, parseSalary); }catch(e){ return ''; }
  const row = data.records.find(r=>r['Há» vÃ  tÃªn']===state.user.name);
  if(!row) return `<div class="panel"><div class="empty">ChÆ°a tÃ¬m tháº¥y dÃ²ng lÆ°Æ¡ng cá»§a báº¡n trong tab "Báº£ng lÆ°Æ¡ng".</div></div>`;
  const skip = ['STT','Há» vÃ  tÃªn','HÆ°á»Ÿng lÆ°Æ¡ng CB?'];
  const U = k=>(k||'').toUpperCase();

  // Tá»•ng thá»±c nháº­n (tá»•ng cuá»‘i cÃ¹ng ngÆ°á»i lÃ¡i xe Ä‘Æ°á»£c lÄ©nh) â€” Æ°u tiÃªn cÃ¡c cÃ¡ch gá»i tÃªn khÃ¡c nhau
  const netTotalKey = Object.keys(row).find(k=>U(k).includes('THá»°C NHáº¬N'))
    || Object.keys(row).find(k=>U(k).includes('THá»°C LÄ¨NH'))
    || Object.keys(row).find(k=>U(k).includes('Tá»”NG THá»°C'));
  // Tá»•ng lÆ°Æ¡ng CB + PC
  const cbPcTotalKey = Object.keys(row).find(k=>U(k).includes('Tá»”NG') && U(k).includes('CB') && U(k).includes('PC'));
  // Tá»•ng lÆ°Æ¡ng chuyáº¿n + PS
  const tripPsTotalKey = Object.keys(row).find(k=>U(k).includes('Tá»”NG') && U(k).includes('CHUYáº¾N'));
  // fallback náº¿u khÃ´ng tÃ¬m Ä‘Æ°á»£c tá»•ng thá»±c nháº­n theo tÃªn cá»¥ thá»ƒ, láº¥y cá»™t "Tá»”NG" cÃ²n láº¡i Ä‘áº§u tiÃªn
  const fallbackTotalKey = netTotalKey || Object.keys(row).find(k=>U(k).includes('Tá»”NG') && k!==cbPcTotalKey && k!==tripPsTotalKey);
  const highlightKeys = [fallbackTotalKey, cbPcTotalKey, tripPsTotalKey].filter(Boolean);

  const restKeys = Object.keys(row).filter(k=>!skip.includes(k) && !highlightKeys.includes(k));
  const basicKeys = restKeys.filter(k=>k.toLowerCase().includes('cÆ¡ báº£n'));
  const tripKeys  = restKeys.filter(k=>k.toLowerCase().includes('chuyáº¿n'));
  const otherKeys = restKeys.filter(k=>!basicKeys.includes(k) && !tripKeys.includes(k));

  const item = (k,cls)=>`
    <div class="salary-item ${cls}"><div class="si-label">${k}</div><div class="si-val">${isNaN(parseMoney(row[k]))?row[k]:formatMoney(parseMoney(row[k]))}</div></div>`;

  return `
    <div class="panel">
      <div class="refresh-row">
        <div><div class="section-title">Báº£ng lÆ°Æ¡ng thÃ¡ng</div><div class="section-sub" style="margin:0;">Sá»‘ liá»‡u tá»•ng há»£p cáº£ thÃ¡ng, cáº­p nháº­t theo tab "Báº£ng lÆ°Æ¡ng" cá»§a quáº£n lÃ½.</div></div>
        <button class="refresh-btn" onclick="invalidate('salary'); loadThenRender();">â†» LÃ m má»›i</button>
      </div>

      ${fallbackTotalKey ? `
      <div class="total-banner">
        <div><div class="tb-label">${fallbackTotalKey}</div></div>
        <div class="tb-value">${formatMoney(parseMoney(row[fallbackTotalKey]))}</div>
      </div>` : ''}

      ${(cbPcTotalKey || tripPsTotalKey) ? `
      <div class="subtotal-row">
        ${cbPcTotalKey ? `<div class="subtotal-card"><div class="tb-label">${cbPcTotalKey}</div><div class="subtotal-value">${formatMoney(parseMoney(row[cbPcTotalKey]))}</div></div>` : ''}
        ${tripPsTotalKey ? `<div class="subtotal-card trip"><div class="tb-label">${tripPsTotalKey}</div><div class="subtotal-value">${formatMoney(parseMoney(row[tripPsTotalKey]))}</div></div>` : ''}
      </div>` : ''}

      ${basicKeys.length ? `<div class="salary-subtitle">LÆ°Æ¡ng cÆ¡ báº£n</div><div class="salary-grid">${basicKeys.map(k=>item(k,'basic')).join('')}</div>` : ''}
      ${tripKeys.length ? `<div class="salary-subtitle">LÆ°Æ¡ng chuyáº¿n</div><div class="salary-grid">${tripKeys.map(k=>item(k,'trip')).join('')}</div>` : ''}
      ${otherKeys.length ? `<div class="salary-subtitle">Phá»¥ cáº¥p khÃ¡c</div><div class="salary-grid">${otherKeys.map(k=>item(k,'')).join('')}</div>` : ''}
    </div>`;
}

