function errorPanel(msg, key, retry){
  window.__retry = window.__retry || {};
  window.__retry[key] = retry;
  return `<div class="panel"><div class="empty" style="border-color:var(--red); color:var(--red);">${msg}</div>
    <button class="refresh-btn" style="margin-top:12px;" onclick="window.__retry['${key}']()">Thá»­ láº¡i</button></div>`;
}

/* ============ MAIN RENDER ============ */
async function loadThenRender(){ render(); }

function render(){
  const app = document.getElementById('app');
  if(!state.user){ app.innerHTML = renderLogin(); return; }

  if(state.user.role==='driver'){
    const tabs = [
      {id:'daily', label:'Thu nháº­p theo ngÃ y'},
      {id:'salary', label:'Báº£ng lÆ°Æ¡ng thÃ¡ng'},
      {id:'attendance', label:'Cháº¥m cÃ´ng'},
    ];
    const tabsHtml = tabs.map(t=>`<button class="tab-btn ${state.driverTab===t.id?'active':''}" onclick="setDriverTab('${t.id}')">${t.label}</button>`).join('');
    app.innerHTML = renderShell(`<div id="tabContent"><div class="loading">Äang táº£iâ€¦</div></div>`, tabsHtml);
    const fn = state.driverTab==='daily' ? renderDailyTab : state.driverTab==='salary' ? renderSalaryTab : renderAttendanceTab;
    fn().then(html=>{ const el = document.getElementById('tabContent'); if(el) el.innerHTML = html; });
  } else {
    const tabs = [
      {id:'salary', label:'Báº£ng lÆ°Æ¡ng'},
      {id:'attendance', label:'Cháº¥m cÃ´ng'},
      {id:'trips', label:'Chi tiáº¿t chuyáº¿n'},
    ];
    const tabsHtml = tabs.map(t=>`<button class="tab-btn ${state.managerTab===t.id?'active':''}" onclick="setManagerTab('${t.id}')">${t.label}</button>`).join('');
    const extra = `<div style="margin-bottom:14px;"><a class="sheet-link" href="${getSheetEditUrl()}" target="_blank" rel="noopener">â†— Má»Ÿ Google Sheet gá»‘c Ä‘á»ƒ chá»‰nh sá»­a</a></div>`;
    app.innerHTML = renderShell(`${extra}<div id="tabContent"><div class="loading">Äang táº£iâ€¦</div></div>`, tabsHtml);
    const fn = state.managerTab==='salary' ? renderManagerSalary : state.managerTab==='attendance' ? renderManagerAttendance : renderManagerTrips;
    fn().then(html=>{ const el = document.getElementById('tabContent'); if(el) el.innerHTML = html; });
  }
}
function setDriverTab(id){ state.driverTab=id; state.openDay=null; render(); }
function setManagerTab(id){ state.managerTab=id; render(); }

